1. use std::{collections::BTreeMap, fs::File, io::BufReader, path::Path};
2. 
3. use testsuite_internal::Case;
4. use walkdir::WalkDir;
5. 
6. pub(crate) type TestCaseTree = BTreeMap<String, TestCaseNode>;
7. 
8. #[derive(Debug)]
9. pub(crate) enum TestCaseNode {
10.     Submodule(TestCaseTree),
11.     TestFile(Vec<Case>),
12. }
13. 
14. impl TestCaseNode {
15.     fn submodule_mut(&mut self) -> Result<&mut TestCaseTree, Box<dyn std::error::Error>> {
16.         match self {
17.             TestCaseNode::Submodule(tree) => Ok(tree),
18.             TestCaseNode::TestFile(_) => Err("Expected a sub-module, found a test file".into()),
19.         }
20.     }
21. }
22. 
23. pub(crate) fn load_suite(
24.     suite_path: &str,
25.     draft: &str,
26. ) -> Result<TestCaseTree, Box<dyn std::error::Error>> {
27.     let full_path = Path::new(suite_path).join("tests").join(draft);
28.     if !full_path.exists() {
29.         return Err(format!("Path does not exist: {}", full_path.display()).into());
30.     }
31.     let mut root = TestCaseTree::new();
32. 
33.     for entry in WalkDir::new(&full_path).into_iter().filter_map(Result::ok) {
34.         let path = entry.path();
35.         if path.is_file() && path.extension().is_some_and(|ext| ext == "json") {
36.             let relative_path = path.strip_prefix(&full_path)?;
37.             let file = File::open(path)?;
38.             let reader = BufReader::new(file);
39.             let cases: Vec<Case> = serde_json::from_reader(reader)?;
40. 
41.             insert_into_module_tree(&mut root, relative_path, cases)?;
42.         }
43.     }
44. 
45.     Ok(root)
46. }
47. 
48. fn insert_into_module_tree(
49.     tree: &mut TestCaseTree,
50.     path: &Path,
51.     cases: Vec<Case>,
52. ) -> Result<(), Box<dyn std::error::Error>> {
53.     let mut current = tree;
54. 
55.     // Navigate through the path components
56.     for component in path.parent().unwrap_or(Path::new("")).components() {
57.         let key = component.as_os_str().to_string_lossy().into_owned();
58.         current = current
59.             .entry(key)
60.             .or_insert_with(|| TestCaseNode::Submodule(TestCaseTree::new()))
61.             .submodule_mut()?;
62.     }
63. 
64.     // Insert the test file
65.     let file_name = path
66.         .file_stem()
67.         .expect("Invalid filename")
68.         .to_string_lossy()
69.         .into_owned();
70.     current.insert(file_name, TestCaseNode::TestFile(cases));
71. 
72.     Ok(())
73. }
